from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts.common.common import LocalBasicPage
from selenium.common.exceptions import ElementClickInterceptedException


class BtsBasicInfo(LocalBasicPage):
    """
    The class corresponding to BTS basic info on selenium_sbts web,
    all operations of BTS basic info will be implemented or added in it.
    """
    _STATUS_BAR_MENU_BUTTON = ('//button[@class="btn minimal-button compact-button '
                               'dropdown-toggle status-bar-menu-button"]')
    _STATUS_BAR_MENU_BUTTON_ELIPSIS = _STATUS_BAR_MENU_BUTTON + '/i'
    _CONNECT_DISCONNECT_BUTTON_XPATH = '//button[@aria-label="Connect Button"]'
    _CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH = '//div[@class="status-bar-menu open"]/ul/li[1]/connection/a'
    _BTS_ID_XPATH = '//*[@class="status-bar-bts-element"]//*[@*="attachTooltipWhenTruncatedText($event)"]'
    _LOAD_IMS2_INPUT_CSS = "ui-file-input[a-text='Load IMS2'] input"
    _LOAD_IMS2_INPUT_BUTTON = "//ui-file-input[@a-text='Load IMS2']//input"

    _OPTIONS_BUTTON = '//otx-product-bar//div[@class="ot-product-end"]//a[@aria-label="Options menu"]'
    _ABOUT_MENU_ITEM = '//div[@id="laf-component"]//span[text()="About"]'

    _VERSION_IN_DIALOG_XPATH = '//ot-about-dialog//div[@class="ot-dialog-subtitle"]'
    _CLOSE_BUTTON_IN_DIALOG_XPATH = '//ot-about-dialog//button[./span[text()="Close"]]'

    def __init__(self, driver):
        super(BtsBasicInfo, self).__init__(driver)

    def check_activate_plan_status(self):
        activate_plan_status_xpath = "//div[contains(@class, 'status-text')]/span"
        self.get_text_by_xpath(activate_plan_status_xpath)

    def get_bts_id(self):
        bts_id = self.get_text_by_xpath(self._BTS_ID_XPATH)
        return bts_id.split("-")[-1]

    def get_bts_status(self, technology):
        tech_xpath = '//div[*[text()="{}"]]/preceding-sibling::div'.format(technology)
        return self.get_text_by_xpath(tech_xpath)

    def get_bts_version(self):
        bts_version_xpath = '//*[@aria-label="Software version"]'
        return self.get_text_by_xpath(bts_version_xpath)

    def connect_to_bts_if_disconnected(self, wait_bar_menu_timeout=30, timeout=90):
        """
        Connects to BTS if Connect button is available and waits for successful connection

        :param wait_bar_menu_timeout: time to wait for status bar menu button loaded after refresh; defaults to 30
        :type timeout: int or str
        :param timeout: time to wait for Connect/Disconnect button to be visible
        :type timeout: int
        """
        if self._check_status_bar_menu_button_type(wait_bar_menu_timeout):
            self._reconnect_with_dropdown_list(timeout)
        else:
            self._reconnect_without_dropdown_list(timeout)

    def _can_be_connected_to_bts(self, dropdown_inside=False, timeout=5):
        """
        Checks in which state Connect/Disconnect button is in.
        :param dropdown_inside: tells if dropdown list exists in
        status bar menu as Connect/Disconnect button is placed in different
        position.
        :type dropdown_inside: bool
        :param timeout: time to wait for button state to be available
        :type timeout: int
        :return: True if button is in 'Connect' state, False otherwise
        :rtype: bool
        """
        if dropdown_inside:
            return self.driver.find_element_by_xpath(
                self._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH).text == 'Connect'
        return self.get_attribute_by_xpath(self._CONNECT_DISCONNECT_BUTTON_XPATH,
                                           'ui-tooltip', timeout) == 'Connect'

    def _check_status_bar_menu_button_type(self, timeout):
        """
        Checks the type of content of status bar menu button as it differs
        between 5G19A and 5G19B/Trunk (newer soft contains
        dropdown list inside).

        :return: True if status bar menu contains dropdown list, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_visibility_by_xpath(xpath=self._STATUS_BAR_MENU_BUTTON_ELIPSIS, timeout=timeout)
            return True
        except TimeoutException:
            return False

    def _reconnect_with_dropdown_list(self, timeout):
        """
        Reconnect with BTS by clicking connect (if it is disconnected),
        when status bar menu button contains dropdown list.
        :param timeout: Time to wait for particular steps being performed.
        :type timeout: int
        """
        self.wait_for_visibility_by_xpath(self._STATUS_BAR_MENU_BUTTON, timeout=timeout)
        try:
            self.click_enabled_element((By.XPATH, self._STATUS_BAR_MENU_BUTTON), timeout=timeout)
        except ElementClickInterceptedException:
            self.click_enabled_element((By.XPATH, self._STATUS_BAR_MENU_BUTTON), timeout=timeout)
        if self._can_be_connected_to_bts(dropdown_inside=True):
            self.click_enabled_element((By.XPATH, self._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH), timeout=timeout)
            self.wait_for_text_not_present_in_element((By.XPATH, self._CONNECT_DISCONNECT_DROPDOWN_LIST_BUTTON_XPATH),
                                                      'Connect', timeout=timeout)

    def _reconnect_without_dropdown_list(self, timeout):
        """
        Reconnect with BTS by clicking connect (if it is disconnected),
        when status bar menu button does not contain dropdown list.
        :param timeout: Time to wait for particular steps being performed.
        :type timeout: int
        """
        self.wait_for_visibility_by_xpath(self._CONNECT_DISCONNECT_BUTTON_XPATH, timeout)
        if self._can_be_connected_to_bts():
            self.click_enabled_element((By.XPATH, self._CONNECT_DISCONNECT_BUTTON_XPATH), timeout=5)
        self.wait_for_text_not_present_in_element((By.XPATH, self._BTS_ID_XPATH), '---', timeout=30)

    def load_ims2(self, file_path, timeout):
        self.click_enabled_element((By.XPATH, self._STATUS_BAR_MENU_BUTTON), timeout)
        self.load_file_from_hidden_button(self._LOAD_IMS2_INPUT_CSS, self._LOAD_IMS2_INPUT_BUTTON, file_path, timeout)
        self._until(lambda _: '-' not in self.get_bts_version(), timeout)

    def get_web_element_manager_version(self, timeout=5):
        self.click_enabled_element((By.XPATH, self._OPTIONS_BUTTON), timeout)
        self.wait_for_visibility_by_xpath(self._ABOUT_MENU_ITEM, timeout)
        self.click_enabled_element((By.XPATH, self._ABOUT_MENU_ITEM), timeout)
        self.wait_for_visibility_by_xpath(self._VERSION_IN_DIALOG_XPATH, timeout)
        version = self.get_text_by_xpath(self._VERSION_IN_DIALOG_XPATH)
        version = version.strip().lstrip("Version:").strip()
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_IN_DIALOG_XPATH), timeout)
        return version
